locals {
  waf_workspaces = ["qa", "staging", "prod", "sha", "bi"]
}

data "terraform_remote_state" "waf" {
  for_each  = toset(local.waf_workspaces)
  backend   = "gcs"
  workspace = each.value
  config = {
    bucket = "liftit-tf-state"
    prefix = "sec/waf"
  }
}

locals {
  waf_rules_sorted = [
    for p in sort([for r in data.terraform_remote_state.waf["qa"].outputs.waf_rules.rules : r.priority]) :
    [for r in data.terraform_remote_state.waf["qa"].outputs.waf_rules.rules : r if r.priority == p][0]
  ]

  waf_preview_by_ws = {
    for ws in local.waf_workspaces : ws => {
      for r in data.terraform_remote_state.waf[ws].outputs.waf_rules.rules :
      r.priority => r.preview
    }
  }

  waf_rules_table_md = join("\\n", concat(
    [
      "| Priority | Action | Description | qa | staging | prod | sha | bi |",
      "|---|---|---|---|---|---|---|---|",
    ],
    [
      for r in local.waf_rules_sorted : format(
        "| %s | `%s` | %s | %s | %s | %s | %s | %s |",
        r.priority, r.action, r.description,
        local.waf_preview_by_ws["qa"][r.priority] ? "preview" : "**enforce**",
        local.waf_preview_by_ws["staging"][r.priority] ? "preview" : "**enforce**",
        local.waf_preview_by_ws["prod"][r.priority] ? "preview" : "**enforce**",
        local.waf_preview_by_ws["sha"][r.priority] ? "preview" : "**enforce**",
        local.waf_preview_by_ws["bi"][r.priority] ? "preview" : "**enforce**",
      )
    ]
  ))
}

input.new_string:
waf_rule_status = {
  for combo in setproduct(local.waf_workspaces, [for r in local.waf_rules_sorted : r.priority]) :
  "${combo[0]}-${combo[1]}" => (
    startswith([for r in local.waf_rules_sorted : r.action if r.priority == combo[1]][0], "deny") ? (
      local.waf_preview_by_ws[combo[0]][combo[1]] ? "log only" : "**BLOCK**"
      ) : (
      startswith([for r in local.waf_rules_sorted : r.action if r.priority == combo[1]][0], "allow") ? (
        local.waf_preview_by_ws[combo[0]][combo[1]] ? "log only" : "allow"
        ) : (
        local.waf_preview_by_ws[combo[0]][combo[1]] ? "log only" : "**RATE-LIMIT**"
      )
    )
  )
}

waf_rules_table_md = join("\\n", concat(
  [
    "| Priority | Action | Description | qa | staging | prod | sha | bi |",
    "|---|---|---|---|---|---|---|---|",
  ],
  [
    for r in local.waf_rules_sorted : format(
      "| %s | `%s` | %s | %s | %s | %s | %s | %s |",
      r.priority, r.action, r.description,
      local.waf_rule_status["qa-${r.priority}"],
